import {AlignMethod, AlignObject, layoutChain} from '@kvisaz/phaser-sugar';
import {ArrayAlignObject} from '@kvisaz/phaser-sugar/dist/layout/ArrayAlignObject/ArrayAlignObject';

interface IProps {
    children: AlignObject[];
    direction?: 'vertical' | 'horizontal';
    gap?: number;
}

/**
 * шорткат для выравнивания объектов в ряд
 * отступ между ними - gap
 * все выраниваются по центру оси
 * **/
export function sideBar({children, direction = 'horizontal', gap = 16}: IProps): ArrayAlignObject {
    const isHorizontal = direction === 'horizontal';
    return layoutChain({
        children,
        alignToNext: isHorizontal ? AlignMethod.RIGHT_TO : AlignMethod.BOTTOM_TO,
        alignToAnchor: isHorizontal ? AlignMethod.CENTER_Y : AlignMethod.CENTER_X,
        nextOffsetX: isHorizontal ? gap : 0,
        nextOffsetY: isHorizontal ? 0 : gap,
    })
}

interface IVerticalProps {
    children: AlignObject[];
    gap?: number;
}

/**
 * шорткат для выравнивания объектов в колонку
 * отступ между ними - gap
 * все выраниваются по центру оси
 * **/
export const sideBarVertical = (props: IVerticalProps) => sideBar({
    ...props,
    direction: 'vertical'
})
