import {SceneEvents} from "../../../common";
import {ISoundPlayerFeatureEvents} from "./events";
import {playerMoveReactionSoundMap, sceneEventSoundMap} from "./soundMap";

interface IProps {
    scene: Phaser.Scene;
}

/** todo 1 перенести на эвенты IGameScenes, убрать свои events.ts **/
export class SoundPlayerFeature {
    private readonly events: SceneEvents<ISoundPlayerFeatureEvents>;

    constructor(private readonly props: IProps) {
        const {scene} = props;

        this.events = new SceneEvents<ISoundPlayerFeatureEvents>({scene});
        this.events.on("playerCardsMoveStart", (data) => {
            const soundConfig = playerMoveReactionSoundMap[data.type];
            if (soundConfig == null) return;
            const {soundName, volume} = soundConfig;
            scene.sound.play(soundName, {volume});
        });
        this.events.on("spiderGameWin", () => {
            const {soundName, volume} = sceneEventSoundMap.spiderGameWin;
            scene.sound.play(soundName, {volume});
        });
        this.events.on("spiderStockDealCardPlace", () => {
            const {soundName, volume} = sceneEventSoundMap.spiderStockDealCardPlace;
            scene.sound.play(soundName, {volume});
        });
    }

    destroy(): void {
        this.events.unSubscribeAll();
    }
}
