export function createViewCardShop(scene: Phaser.Scene): Phaser.GameObjects.Container {
  const view = createContainerFromViewData(scene, viewCardShopData);

  const uiDialogBgLightNine40 = createAssetChild(scene, viewCardShopData.children['ui.dialog.bg.light.nine.40']);
  setLeftTop(
    uiDialogBgLightNine40,
    viewCardShopData.children['ui.dialog.bg.light.nine.40'].x - viewCardShopData.width / 2,
    viewCardShopData.children['ui.dialog.bg.light.nine.40'].y - viewCardShopData.height / 2,
  );
  view.add(uiDialogBgLightNine40);

  const textCardShopTitle = createTextChild(scene, viewCardShopData.children['text.CardShop.Title']);
  setLeftTop(
    textCardShopTitle,
    viewCardShopData.children['text.CardShop.Title'].x - viewCardShopData.width / 2,
    viewCardShopData.children['text.CardShop.Title'].y - viewCardShopData.height / 2,
  );
  view.add(textCardShopTitle);

  const buttonBack = createButtonBack(scene);
  setLeftTop(
    buttonBack,
    viewCardShopData.children.buttonBack.x - viewCardShopData.width / 2,
    viewCardShopData.children.buttonBack.y - viewCardShopData.height / 2,
  );
  view.add(buttonBack);

  const buttonCardShopSelectClassic = buildButtonCardShopSelectClassic(scene);
  setLeftTop(
    buttonCardShopSelectClassic,
    viewCardShopData.children['button.CardShop.Select.Classic'].x - viewCardShopData.width / 2,
    viewCardShopData.children['button.CardShop.Select.Classic'].y - viewCardShopData.height / 2,
  );
  view.add(buttonCardShopSelectClassic);

  const buttonCardShopSelectChibi = buildButtonCardShopSelectChibi(scene);
  setLeftTop(
    buttonCardShopSelectChibi,
    viewCardShopData.children['button.CardShop.Select.Chibi'].x - viewCardShopData.width / 2,
    viewCardShopData.children['button.CardShop.Select.Chibi'].y - viewCardShopData.height / 2,
  );
  view.add(buttonCardShopSelectChibi);

  return view;
}

/**
 * Собирает вложенный view только из его direct children.
 * Родительский builder вызывает эту функцию и не разворачивает внутренности сам.
 */
function buildButtonCardShopSelectClassic(scene: Phaser.Scene): Phaser.GameObjects.Container {
  const data = viewCardShopData.children['button.CardShop.Select.Classic'];
  const view = createContainerFromViewData(scene, data);

  const textBtCardShopSelectClassic = createTextChild(scene, data.children['text.Bt.CardShop.Select.Classic']);
  setLeftTop(
    textBtCardShopSelectClassic,
    data.children['text.Bt.CardShop.Select.Classic'].x - data.width / 2,
    data.children['text.Bt.CardShop.Select.Classic'].y - data.height / 2,
  );
  view.add(textBtCardShopSelectClassic);

  const chooseButtonDead = createAssetChild(scene, data.children['choose.button.dead']);
  setLeftTop(
    chooseButtonDead,
    data.children['choose.button.dead'].x - data.width / 2,
    data.children['choose.button.dead'].y - data.height / 2,
  );
  view.add(chooseButtonDead);

  const cardsTripleClassic = createAssetChild(scene, data.children['cards.triple.classic']);
  setLeftTop(
    cardsTripleClassic,
    data.children['cards.triple.classic'].x - data.width / 2,
    data.children['cards.triple.classic'].y - data.height / 2,
  );
  view.add(cardsTripleClassic);

  return view;
}

