interface IProps {
    scene: Phaser.Scene;
}

export function createViewSettings({scene}: IProps): Phaser.GameObjects.Container {
    const currentPlayerData = GameServiceProvider.get().getPlayerData();
    const settings = currentPlayerData.settings;


    const view = createContainerFromViewData(scene, viewSettingsData);

    const uiDialogBgLightNine40 = createAssetChild(scene, viewSettingsData.children['ui.dialog.bg.light.nine.40']);
    setLeftTop(
        uiDialogBgLightNine40,
        viewSettingsData.children['ui.dialog.bg.light.nine.40'].x - viewSettingsData.width / 2,
        viewSettingsData.children['ui.dialog.bg.light.nine.40'].y - viewSettingsData.height / 2,
    );
    view.add(uiDialogBgLightNine40);

    const textSettingsTitle = createTextChild(scene, viewSettingsData.children.textSettingsTitle);
    setLeftTop(
        textSettingsTitle,
        viewSettingsData.children.textSettingsTitle.x - viewSettingsData.width / 2,
        viewSettingsData.children.textSettingsTitle.y - viewSettingsData.height / 2,
    );
    centerX(uiDialogBgLightNine40, textSettingsTitle);
    view.add(textSettingsTitle);

    const viewSettingSound = buildViewSettingSound(scene);
    setLeftTop(
        viewSettingSound,
        viewSettingsData.children.viewSettingSound.x - viewSettingsData.width / 2,
        viewSettingsData.children.viewSettingSound.y - viewSettingsData.height / 2,
    );
    view.add(viewSettingSound);

    makeSwitch({
        initState: true,
        view: viewSettingSound,
        onSwitch: switched => {
            console.log(' sound switched', switched)
        }
    })

    const viewSettingMusic = buildViewSettingMusic(scene);
    setLeftTop(
        viewSettingMusic,
        viewSettingsData.children.viewSettingMusic.x - viewSettingsData.width / 2,
        viewSettingsData.children.viewSettingMusic.y - viewSettingsData.height / 2,
    );
    view.add(viewSettingMusic);

    makeSwitch({
        initState: true,
        view: viewSettingMusic,
        onSwitch: switched => {
            console.log('music switched', switched)
        }
    })

    const buttonBack = createButtonBack(scene);
    setLeftTop(
        buttonBack,
        viewSettingsData.children.buttonBack.x - viewSettingsData.width / 2,
        viewSettingsData.children.buttonBack.y - viewSettingsData.height / 2,
    );
    view.add(buttonBack);

    return view;
}

/**
 * Собирает вложенный view только из его direct children.
 * Родительский builder вызывает эту функцию и не разворачивает внутренности сам.
 */
function buildViewSettingSound(scene: Phaser.Scene): Phaser.GameObjects.Container {
    const data = viewSettingsData.children.viewSettingSound;
    const view = createContainerFromViewData(scene, data);

    const viewSettingSoundOn = buildViewSettingSoundOn(scene);
    setLeftTop(
        viewSettingSoundOn,
        data.children.viewSettingSoundOn.x - data.width / 2,
        data.children.viewSettingSoundOn.y - data.height / 2,
    );
    view.add(viewSettingSoundOn);

    const viewSettingSoundOff = buildViewSettingSoundOff(scene);
    setLeftTop(
        viewSettingSoundOff,
        data.children.viewSettingSoundOff.x - data.width / 2,
        data.children.viewSettingSoundOff.y - data.height / 2,
    );
    view.add(viewSettingSoundOff);

    return view;
}

