    /**
     *  Texts View Elements
     ***/
    textSmallStart(label: string) {
        const fontFamily = fontAssets.russoOneRegular.fontFamily;
        const fontSizePx = 24;
        const fontCssColor = '#FFFFFF';
        const strokeCssColor = 'rgba(0,0,0, 65)';
        const strokeThickness = 6;

        const textStyle: Phaser.Types.GameObjects.Text.TextStyle = {
            fontFamily,
            fontSize: `${fontSizePx}px`,
            color: fontCssColor,
            strokeThickness,
            stroke: strokeCssColor,
        };
        const textObj = new Phaser.GameObjects.Text(this.scene, 0, 0, label, textStyle);
        this.scene.add.existing(textObj);
        return textObj;
    }


    textDecorative(text: string, options: ITextBuildProps = {}): Phaser.GameObjects.Text {
        const defaultFontSize = "64px";

        function selectFamily(options: ITextBuildProps) {
            if (options.weight === "regular") return autoAssetsConfig.fonts.alegreyaSCRegular.fontFamily;
            return autoAssetsConfig.fonts.alegreyaSCExtrabold.fontFamily;
        }

        const style: Phaser.Types.GameObjects.Text.TextStyle = {
            ...options,
            fontFamily: selectFamily(options),
            fontSize: options.fontSize ?? defaultFontSize,
        };

        return this.scene.add.existing(new Phaser.GameObjects.Text(this.scene, 0, 0, text, style));
    }

    textMain(text: string, options: ITextBuildProps = {}): Phaser.GameObjects.Text {
        const defaultFontSize = "32px";

        function selectFamily(options: ITextBuildProps) {
            if (options.weight === "bold") return autoAssetsConfig.fonts.robotoBold.fontFamily;
            if (options.weight === "semibold") return autoAssetsConfig.fonts.robotoSemibold.fontFamily;
            return autoAssetsConfig.fonts.robotoRegular.fontFamily;
        }

        const fontSize = options.fontSize ?? defaultFontSize;

        const style: Phaser.Types.GameObjects.Text.TextStyle = {
            ...options,
            fontFamily: selectFamily(options),
            fontSize,
        };

        return this.scene.add.existing(new Phaser.GameObjects.Text(this.scene, 0, 0, text, style));
    }

    textStartScreenTitle(): Phaser.GameObjects.Text {
        const label = getLocalizedText("start.logo.title");
        const fontSizePx = 100;
        const fontCssColor = '#FF9735';
        const strokeCssColor = '#FFFFFF';

        const textStyle: Phaser.Types.GameObjects.Text.TextStyle = {
            fontFamily: fontAssets.rubikBubblesRegular.fontFamily,
            fontSize: `${fontSizePx}px`,
            color: fontCssColor,
            strokeThickness: 14,
            stroke: strokeCssColor,
        };
        const textObj = new Phaser.GameObjects.Text(this.scene, 0, 0, label, textStyle);
        this.scene.add.existing(textObj);
        return textObj;
    }

