import { SceneEvents } from "../../../../common";
import { SoundPlayer } from "../../../../common/sound/SoundPlayer";
import { onSceneShutdown } from "../../../../common/scenes";
import { GameServiceProvider } from "../../../../services";
import { ISceneSoundManagerEvents } from "./events";
import { ISceneSoundManagerProps } from "./types";

const DEFAULT_MUSIC_CHANNEL_KEY = "music";

/**
 * Scene-level orchestrator для фоновой музыки и настроек звука.
 *
 * Задача модуля:
 * - держать локальный `SoundPlayer` для текущей сцены;
 * - слушать совместимое scene-событие `gameSettingsUpdated`;
 * - переводить настройки игрока в простые sound events:
 *   `soundPlayerSetMuted`, `soundPlayerSetChannelMuted`, `soundPlayerPlay`.
 *
 * Границы ответственности:
 * - не работает напрямую с UI настроек;
 * - не открывает модалки и не знает про конкретные кнопки;
 * - живет ровно столько же, сколько живет сцена.
 */
export class SceneSoundManager {
  private readonly sceneEvents: SceneEvents<ISceneSoundManagerEvents>;
  private readonly soundPlayer: SoundPlayer;
  private readonly musicChannelKey: string;

  constructor(private readonly props: ISceneSoundManagerProps) {
    this.sceneEvents = new SceneEvents<ISceneSoundManagerEvents>({ scene: props.scene });
    this.soundPlayer = new SoundPlayer({ scene: props.scene });
    this.musicChannelKey = props.musicChannelKey ?? DEFAULT_MUSIC_CHANNEL_KEY;

    this.sceneEvents.on("gameSettingsUpdated", this.sync.bind(this));
    onSceneShutdown(props.scene, () => this.destroy());

    this.sync(GameServiceProvider.get().getPlayerData().settings);
  }

  destroy(): void {
    this.sceneEvents.unSubscribeAll();
    this.soundPlayer.destroy();
  }

  /**
   * Синхронизирует runtime-звук сцены с настройками игрока.
   *
   * Поведение:
   * - глобальный звук выключается через `soundPlayerSetMuted`;
   * - music channel выключается отдельно через `soundPlayerSetChannelMuted`;
   * - при включенных sound + music менеджер гарантирует, что фоновая музыка
   *   будет запущена или продолжена idempotent-командой `soundPlayerPlay`.
   */
  private sync(settings: ISceneSoundManagerEvents["gameSettingsUpdated"]): void {
    this.sceneEvents.emit("soundPlayerSetMuted", {
      muted: !settings.isSoundOn,
    });

    this.sceneEvents.emit("soundPlayerSetChannelMuted", {
      channelKey: this.musicChannelKey,
      muted: !settings.isMusicOn,
    });

    if (!settings.isSoundOn || !settings.isMusicOn) {
      return;
    }

    this.sceneEvents.emit("soundPlayerPlay", {
      soundKey: this.props.musicSoundKey,
      channelKey: this.musicChannelKey,
      loop: this.props.musicLoop ?? true,
      volume: this.props.musicVolume,
    });
  }
}
